1	     1	import AppKit
2	     2	
3	     3	/// The row marks of the Clip inspector (road map 9 §5, spec §11 CI-7): what
4	     4	/// the SELECTED action does to one row, in a 14 pt gutter before its label.
5	     5	///
6	     6	/// A row's mark is derived from two lists of `"group.key"` paths: the keys
7	     7	/// its control WRITES — taken from the row's own `ops(read())` at build time,
8	     8	/// so a write that lands on the action's end patch and one that lands on the
9	     9	/// base props name the same key — and the keys it only FOLLOWS (Gain follows
10	    10	/// Volume). Both empty is `.none`, action or no action: a row that says
11	    11	/// nothing about what it writes (a readout, a Document-tab row) is never
12	    12	/// marked ⊘ by omission.
13	    13	enum RowMark: Equatable {
14	    14	    /// Nothing to say — the gutter stays blank.
15	    15	    case none
16	    16	    /// ◆ — the row writes a key the selected action's end patch holds.
17	    17	    case keyed
18	    18	    /// ◆ and "at end" — the same, for a discrete control, which switches at
19	    19	    /// the action's end rather than ramping.
20	    20	    case keyedAtEnd
21	    21	    /// ◇ — ANOTHER action keys it; the number is that action's time-order
22	    22	    /// number (`ActionBands.ordered`).
23	    23	    case other(Int)
24	    24	    /// ○ — the row follows a keyed value without writing it.
25	    25	    case follows
26	    26	    /// ⊘ — the row writes the clip whatever is selected (CI-3, motion, a
27	    27	    /// list's length): the selected action cannot animate it.
28	    28	    case notAnimatable
29	    29	}
30	    30	
31	    31	/// A section's marks, folded from its gutters: how many KEYS its rows write
32	    32	/// that the selected action holds (CI-6's count, so a section's `◆N` agrees
33	    33	/// with its sub-tab's), whether any row is ◇, whether every row that writes
34	    34	/// is ⊘, whether the section differs from its default (spec §11 CI-9), and
35	    35	/// the number of the action it is EDITING — the selected one, when any of
36	    36	/// its rows animates — which is what turns its Reset slot into Clear.
37	    37	struct SectionMarks: Equatable {
38	    38	    var keyed: Int
39	    39	    var other: Bool
40	    40	    var allNotAnimatable: Bool
41	    41	    var differs = false
42	    42	    var editing: Int? = nil
43	    43	
44	    44	    static let empty = SectionMarks(keyed: 0, other: false, allNotAnimatable: false)
45	    45	}
46	    46	
47	    47	/// A row's default (spec §11 CI-9): the undo name its reset runs under,
48	    48	/// whether the row differs from its default now, and the ops that put the
49	    49	/// default back — on the base props, or on the selected action's end.
50	    50	struct InspectorRowDefault {
51	    51	    let name: String
52	    52	    let differs: () -> Bool
53	    53	    let ops: () -> [ReelOp]
54	    54	
55	    55	    /// The default a typed row derives from its own `read` and `ops`: the
56	    56	    /// value `read` answers in `.defaults`, written through `ops`.
57	    57	    static func derived<T: Equatable>(
58	    58	        _ binding: InspectorBinding, name: String, read: @escaping () -> T,
59	    59	        ops: @escaping (T) -> [ReelOp]
60	    60	    ) -> InspectorRowDefault {
61	    61	        InspectorRowDefault(
62	    62	            name: name,
63	    63	            differs: { [weak binding] in
64	    64	                guard let binding else { return false }
65	    65	                return read() != binding.at(.defaults, read)
66	    66	            },
67	    67	            ops: { [weak binding] in
68	    68	                guard let binding else { return [] }
69	    69	                return ops(binding.at(.defaults, read))
70	    70	            })
71	    71	    }
72	    72	}
