74	    74	/// The 14 pt column in front of every `inspectorRow`, blank at `.none`. It is
75	    75	/// the row's FIRST subview, so `refreshOptionControls(in:)` refreshes it
76	    76	/// before the row's controls — which is what lets its `refresh()` set the
77	    77	/// label's ink and the controls' keyed border with nothing after it undoing
78	    78	/// them (`OptionFieldControl.refresh()` never touches its layer).
79	    79	///
80	    80	/// Hovered while keyed (spec §11 CI-9) its ◆ draws as a × and a click on it
81	    81	/// removes the row's keys from the selected action. The row sets `hovered`
82	    82	/// (`InspectorRowView`), because the pointer is over the row, not the gutter.
83	    83	final class InspectorMarkGutter: NSView, OptionControl {
84	    84	    let writes: [String]
85	    85	    let follows: [String]
86	    86	    private(set) var mark: RowMark = .none
87	    87	    private(set) weak var binding: InspectorBinding?
88	    88	    let animates: Bool
89	    89	    let `default`: InspectorRowDefault?
90	    90	    private let discrete: Bool
91	    91	    private weak var label: InspectorRowLabel?
92	    92	    private let controls: [NSView]
93	    93	
94	    94	    /// ◆ or ◆ "at end".
95	    95	    var isKeyed: Bool { mark == .keyed || mark == .keyedAtEnd }
96	    96	    var hovered = false {
97	    97	        didSet {
98	    98	            guard hovered != oldValue else { return }
99	    99	            needsDisplay = true
100	   100	            updateToolTip()
101	   101	        }
102	   102	    }
103	   103	    /// The × — hover alone is not enough, the row must be keyed.
104	   104	    var showsRemove: Bool { hovered && isKeyed }
105	   105	
106	   106	    init(
107	   107	        binding: InspectorBinding?, writes: [ReelOp], follows: [ReelOp],
108	   108	        label: InspectorRowLabel?, controls: [NSView], discrete: Bool,
109	   109	        default: InspectorRowDefault?
110	   110	    ) {
111	   111	        self.writes = InspectorBinding.paths(of: writes)
112	   112	        self.follows = InspectorBinding.paths(of: follows)
113	   113	        self.binding = binding
114	   114	        self.animates = InspectorBinding.animates(writes)
115	   115	        self.default = `default`
116	   116	        self.discrete = discrete
117	   117	        self.label = label
118	   118	        self.controls = controls
119	   119	        super.init(frame: .zero)
120	   120	        translatesAutoresizingMaskIntoConstraints = false
121	   121	        widthAnchor.constraint(equalToConstant: InspectorMetrics.markGutter).isActive = true
122	   122	        refresh()
123	   123	    }
124	   124	
125	   125	    @available(*, unavailable)
126	   126	    required init?(coder: NSCoder) {
127	   127	        fatalError("InspectorMarkGutter does not support NSCoder")
128	   128	    }
129	   129	
130	   130	    override var isFlipped: Bool { true }
131	   131	
132	   132	    /// The keys this row writes that the selected action holds — what a
133	   133	    /// section's `◆N` is the union of.
134	   134	    func keyedWrites() -> Set<String> {
135	   135	        guard let binding else { return [] }
136	   136	        return binding.keyedPaths().intersection(writes)
137	   137	    }
138	   138	
139	   139	    /// Takes the row's keys out of the selected action's end patch — the ×
140	   140	    /// and the menu's "Remove from action N".
141	   141	    func removeFromAction() {
142	   142	        guard let binding else { return }
143	   143	        binding.apply("Remove from Action", binding.clearOps(keyedWrites()))
144	   144	    }
145	   145	
146	   146	    func refresh() {
147	   147	        let next = binding?.mark(
148	   148	            writes: writes, follows: follows, animates: animates, discrete: discrete) ?? .none
149	   149	        if next != mark {
150	   150	            mark = next
151	   151	            needsDisplay = true
152	   152	        }
153	   153	        let ink = isKeyed ? DS.textStrong : mark == .notAnimatable ? DS.textFaint : DS.textMuted
154	   154	        if let label, label.textColor != ink { label.textColor = ink }
155	   155	        updateToolTip()
156	   156	        paintBorders()
157	   157	    }
158	   158	
159	   159	    private func updateToolTip() {
160	   160	        if showsRemove, let number = binding?.selectedActionNumber {
161	   161	            toolTip = "Remove from action \(number)"
162	   162	        } else if case .other(let number) = mark {
163	   163	            toolTip = "Changed by action \(number)"
164	   164	        } else {
165	   165	            toolTip = nil
166	   166	        }
167	   167	    }
168	   168	
169	   169	    /// The keyed rows' 1 pt action-ink border on their fields and popups.
170	   170	    private func paintBorders() {
171	   171	        let keyed = isKeyed
172	   172	        for control in controls where control is OptionFieldControl
173	   173	            || control is OptionPopupControl
174	   174	        {
175	   175	            if keyed { control.wantsLayer = true }
176	   176	            guard let layer = control.layer else { continue }
177	   177	            layer.borderWidth = keyed ? 1 : 0
178	   178	            if keyed {
179	   179	                effectiveAppearance.performAsCurrentDrawingAppearance {
180	   180	                    layer.borderColor = DS.action.cgColor
181	   181	                }
182	   182	            }
183	   183	        }
184	   184	    }
185	   185	
186	   186	    /// A `CGColor` does not follow the appearance, so the border is resolved
187	   187	    /// again when it changes.
188	   188	    override func viewDidChangeEffectiveAppearance() {
189	   189	        super.viewDidChangeEffectiveAppearance()
190	   190	        paintBorders()
191	   191	    }
192	   192	
193	   193	    override func mouseDown(with event: NSEvent) {
194	   194	        guard showsRemove else {
195	   195	            super.mouseDown(with: event)
196	   196	            return
197	   197	        }
198	   198	        removeFromAction()
199	   199	    }
200	   200	
201	   201	    override func draw(_ dirtyRect: NSRect) {
202	   202	        let glyph: String
203	   203	        let ink: NSColor
204	   204	        switch mark {
205	   205	        case .none: return
206	   206	        case .keyed, .keyedAtEnd:
207	   207	            (glyph, ink) = showsRemove ? ("×", DS.textMuted) : ("◆", DS.action)
208	   208	        case .follows: (glyph, ink) = ("○", DS.action)
209	   209	        case .other: (glyph, ink) = ("◇", DS.textFaint)
210	   210	        case .notAnimatable: (glyph, ink) = ("⊘", DS.textFaint)
211	   211	        }
212	   212	        let attributes: [NSAttributedString.Key: Any] = [.font: DS.mono(10), .foregroundColor: ink]
213	   213	        let size = glyph.size(withAttributes: attributes)
214	   214	        glyph.draw(
215	   215	            at: NSPoint(x: (bounds.width - size.width) / 2, y: (bounds.height - size.height) / 2),
216	   216	            withAttributes: attributes)
217	   217	    }
218	   218	}
