220	   220	/// A short mono tag after a row's controls — "at end" in the action ink, or
221	   221	/// the coral "now …" of a field-only row. Hidden while `text` answers nil.
222	   222	final class InspectorRowTag: NSTextField, OptionControl {
223	   223	    private let text: () -> String?
224	   224	
225	   225	    init(text: @escaping () -> String?, color: NSColor) {
226	   226	        self.text = text
227	   227	        super.init(frame: .zero)
228	   228	        isEditable = false
229	   229	        isBordered = false
230	   230	        isBezeled = false
231	   231	        drawsBackground = false
232	   232	        font = DS.mono(10)
233	   233	        textColor = color
234	   234	        // One line: a wrapping tag gives its width away to its neighbours by
235	   235	        // growing tall, so a row short of room squeezed "at end" into a
236	   236	        // column instead of narrowing the field beside it (B87, G-34 (l)).
237	   237	        maximumNumberOfLines = 1
238	   238	        refresh()
239	   239	    }
240	   240	
241	   241	    @available(*, unavailable)
242	   242	    required init?(coder: NSCoder) {
243	   243	        fatalError("InspectorRowTag does not support NSCoder")
244	   244	    }
245	   245	
246	   246	    func refresh() {
247	   247	        let next = text()
248	   248	        if stringValue != (next ?? "") { stringValue = next ?? "" }
249	   249	        isHidden = next == nil
250	   250	    }
251	   251	}
252	   252	
253	   253	/// The handoff's boxed mono 9 "clip" tag after a lone ⊘ button in an
254	   254	/// animatable section — Normalize, which writes the clip whatever action is
255	   255	/// selected (#102). Shown while an action is selected, CI-7's ⊘ condition.
256	   256	/// Its own view: `OptionButtonControl` is shared chrome and is not forked.
257	   257	final class InspectorClipTag: NSView, OptionControl {
258	   258	    static let text = "clip"
259	   259	    private weak var binding: InspectorBinding?
260	   260	
261	   261	    init(binding: InspectorBinding) {
262	   262	        self.binding = binding
263	   263	        super.init(frame: .zero)
264	   264	        toolTip = "Actions don't animate this. It changes the clip."
265	   265	        refresh()
266	   266	    }
267	   267	
268	   268	    @available(*, unavailable)
269	   269	    required init?(coder: NSCoder) {
270	   270	        fatalError("InspectorClipTag does not support NSCoder")
271	   271	    }
272	   272	
273	   273	    override var isFlipped: Bool { true }
274	   274	
275	   275	    override var intrinsicContentSize: NSSize {
276	   276	        let width = Self.text.size(withAttributes: [.font: DS.mono(9)]).width
277	   277	        return NSSize(width: ceil(width) + 10, height: 17)
278	   278	    }
279	   279	
280	   280	    func refresh() {
281	   281	        isHidden = binding?.selectedAction == nil
282	   282	    }
283	   283	
284	   284	    override func draw(_ dirtyRect: NSRect) {
285	   285	        DS.border.setStroke()
286	   286	        let box = NSBezierPath(rect: bounds.insetBy(dx: 0.5, dy: 0.5))
287	   287	        box.lineWidth = 1
288	   288	        box.stroke()
289	   289	        let attributes: [NSAttributedString.Key: Any] = [
290	   290	            .font: DS.mono(9), .foregroundColor: DS.textMuted,
291	   291	        ]
292	   292	        let size = Self.text.size(withAttributes: attributes)
293	   293	        Self.text.draw(
294	   294	            at: NSPoint(x: (bounds.width - size.width) / 2, y: (bounds.height - size.height) / 2),
295	   295	            withAttributes: attributes)
296	   296	    }
297	   297	}
298	   298	
299	   299	// MARK: - The mark queries
300	   300	
301	   301	extension InspectorBinding {
302	   302	    /// The `"group.key"` paths a list of ops writes: `set_video`, `set_audio`
303	   303	    /// and `set_text` by their patch's keys, `set_graphic` and an end's
304	   304	    /// `graphic` by `graphicPaths`, `set_action_end` by each group of its
305	   305	    /// patch, and `set_speed` by `speed`, the end's top-level rate key (spec
306	   306	    /// §11 SR-21 (c)); every other op (a trim, a reverse) writes none.
307	   307	    static func paths(of ops: [ReelOp]) -> [String] {
308	   308	        let groups = ["set_video": "video", "set_audio": "audio", "set_text": "text"]
309	   309	        var found = Set<String>()
310	   310	        for op in ops {
311	   311	            if op.name == "set_speed" {
312	   312	                found.insert("speed")
313	   313	                continue
314	   314	            }
315	   315	            guard let patch = op.args["patch"] as? [String: Any] else { continue }
316	   316	            if let group = groups[op.name] {
317	   317	                found.formUnion(patch.keys.map { group + "." + $0 })
318	   318	            } else if op.name == "set_action_end" {
319	   319	                found.formUnion(paths(inPatch: patch))
320	   320	                found.formUnion(op.args["off"] as? [String] ?? [])  // keyed OFF (CI-14)
321	   321	            } else if op.name == "set_graphic" { found.formUnion(graphicPaths(patch)) }
322	   322	        }
323	   323	        return found.sorted()
324	   324	    }
325	   325	
326	   326	    /// An end patch's paths, spelled as `paths(of:)` spells them: a top-level
327	   327	    /// key that is not a group — `speed` (spec §11 SR-21 (c)) — by its own
328	   328	    /// name.
329	   329	    private static func paths(inPatch patch: [String: Any]) -> [String] {
330	   330	        patch.flatMap { group, value -> [String] in
331	   331	            if group == "graphic" { return graphicPaths(value) }
332	   332	            guard let fields = value as? [String: Any] else { return group == "speed" ? [group] : [] }
333	   333	            return fields.keys.map { group + "." + $0 }
334	   334	        }
335	   335	    }
336	   336	
337	   337	    /// A `graphic` group's paths, `set_graphic`'s patch or an end's (spec §11
338	   338	    /// G-34 (l)): `graphic.props.<key>` per prop, none for the core's
339	   339	    /// `kinds`, and `graphic.<key>` for any other key — `set_graphic`'s
340	   340	    /// `width`, `height` and `length`, which no end takes, so their rows are
341	   341	    /// ⊘ while an action is selected.
342	   342	    private static func graphicPaths(_ group: Any) -> [String] {
343	   343	        guard let body = group as? [String: Any] else { return [] }
344	   344	        var paths: [String] = []
345	   345	        for (key, value) in body where key != "kinds" {
346	   346	            if key == "props" {
347	   347	                let props = (value as? [String: Any])?.keys.map { "graphic.props." + $0 }
348	   348	                paths += props ?? []
349	   349	            } else {
350	   350	                paths.append("graphic." + key)
351	   351	            }
352	   352	        }
353	   353	        return paths
354	   354	    }
355	   355	
356	   356	    /// Whether any of the ops reaches an action's end patch.
357	   357	    static func animates(_ ops: [ReelOp]) -> Bool {
358	   358	        ops.contains { $0.name == "set_action_end" }
359	   359	    }
360	   360	
361	   361	    /// The selected action's end patch, as paths.
362	   362	    func keyedPaths() -> Set<String> {
363	   363	        guard let action = selectedAction else { return [] }
364	   364	        return Set(Self.paths(inPatch: action.end.dictionary))
365	   365	    }
366	   366	
367	   367	    /// The time-order numbers of the single selected clip's OTHER actions
368	   368	    /// whose end patch holds any of `paths`. One clip only: an action's
369	   369	    /// number is its clip's, and two clips' numbers would say nothing.
370	   370	    func otherActions(keying paths: [String]) -> [Int] {
371	   371	        guard isSingle, let clip = primary, !paths.isEmpty else { return [] }
372	   372	        let wanted = Set(paths)
373	   373	        let selected = selectedAction?.id
374	   374	        return ActionBands.ordered(clip).enumerated().compactMap { index, action in
375	   375	            guard action.id != selected,
376	   376	                  !wanted.isDisjoint(with: Self.paths(inPatch: action.end.dictionary))
377	   377	            else { return nil }
378	   378	            return index + 1
379	   379	        }
380	   380	    }
381	   381	
382	   382	    /// The selected action's time-order NUMBER on the single selected clip
383	   383	    /// (`ActionBands.ordered`), nil with none selected.
384	   384	    var selectedActionNumber: Int? {
385	   385	        guard let id = selectedAction?.id, let clip = primary else { return nil }
386	   386	        return ActionBands.ordered(clip).firstIndex { $0.id == id }.map { $0 + 1 }
387	   387	    }
388	   388	
389	   389	    /// The id of the single selected clip's action numbered `number`.
390	   390	    func actionID(number: Int) -> UInt32? {
391	   391	        guard isSingle, let clip = primary else { return nil }
392	   392	        let ordered = ActionBands.ordered(clip)
393	   393	        return ordered.indices.contains(number - 1) ? ordered[number - 1].id : nil
394	   394	    }
395	   395	
396	   396	    /// ONE `set_action_end` that nulls every `"group.key"` of `paths` in the
397	   397	    /// selected action's end patch — a null REMOVES the key (spec §11 CI-9),
398	   398	    /// so the value falls back to what was held. A one-part path (`speed`,
399	   399	    /// spec §11 SR-21 (c)) is nulled at the patch's top. Nothing without a
400	   400	    /// selected action on a single clip, or without a path.
401	   401	    func clearOps(_ paths: Set<String>) -> [ReelOp] {
402	   402	        guard let action = selectedAction, isSingle, let clip = primary, !paths.isEmpty
403	   403	        else { return [] }
404	   404	        var patch: [String: Any] = [:]
405	   405	        for path in paths.sorted() {
406	   406	            let parts = path.split(separator: ".", maxSplits: 1).map(String.init)
407	   407	            if parts.count == 1 {
408	   408	                patch[parts[0]] = NSNull()
409	   409	                continue
410	   410	            }
411	   411	            guard parts.count == 2 else { continue }
412	   412	            var group = patch[parts[0]] as? [String: Any] ?? [:]
413	   413	            if parts[0] == "graphic", parts[1].hasPrefix("props.") {
414	   414	                // An end's prop nests one level deeper (G-34 (a)).
415	   415	                var props = group["props"] as? [String: Any] ?? [:]
416	   416	                props[String(parts[1].dropFirst("props.".count))] = NSNull()
417	   417	                group["props"] = props
418	   418	            } else {
419	   419	                group[parts[1]] = NSNull()
420	   420	            }
421	   421	            patch[parts[0]] = group
422	   422	        }
423	   423	        guard !patch.isEmpty else { return [] }
424	   424	        return [.setActionEndRaw(clip: clip.id, action: action.id, patch: patch)]
425	   425	    }
426	   426	
427	   427	    /// Spec §11 CI-7's rule, in its order.
428	   428	    func mark(writes: [String], follows: [String], animates: Bool, discrete: Bool) -> RowMark {
429	   429	        if writes.isEmpty && follows.isEmpty { return .none }
430	   430	        if selectedAction != nil {
431	   431	            if !writes.isEmpty && !animates { return .notAnimatable }
432	   432	            let keyed = keyedPaths()
433	   433	            if !keyed.isDisjoint(with: writes) { return discrete ? .keyedAtEnd : .keyed }
434	   434	            if !keyed.isDisjoint(with: follows) { return .follows }
435	   435	        }
436	   436	        if let number = otherActions(keying: writes + follows).first { return .other(number) }
437	   437	        return .none
438	   438	    }
439	   439	
440	   440	    /// The value `read` answers at the PLAYHEAD, when the playhead is inside
441	   441	    /// the first selected clip; nil otherwise.
442	   442	    func nowValue(_ read: () -> Double) -> Double? {
443	   443	        guard let clip = primary, clip.start <= playhead, playhead < clip.end else { return nil }
444	   444	        return at(.playhead, read)
445	   445	    }
446	   446	
447	   447	    /// The value `read` answers at the selected action's START; nil with no
448	   448	    /// action selected.
449	   449	    func startValue(_ read: () -> Double) -> Double? {
450	   450	        guard selectedAction != nil else { return nil }
451	   451	        return at(.start, read)
452	   452	    }
453	   453	}
454	     1	import AppKit
455	     2	
456	     3	/// One inspector row (spec §11 CI-9): the horizontal stack `inspectorRow`
457	     4	/// always built — the mark gutter FIRST, with no spacing after it (CI-7) —
458	     5	/// which now tracks the pointer over itself and answers a context menu.
459	     6	///
460	     7	/// The pointer is over the ROW, so the row tells its gutter (`hovered`); the
461	     8	/// gutter decides whether that makes its ◆ a ×. The menu never reads the
462	     9	/// hover: a window that is not key tracks none, and a right-click there must
463	    10	/// offer the same items.
464	    11	///
