3	     3	/// The row marks of the Clip inspector (road map 9 §5, spec §11 CI-7): what
4	     4	/// the SELECTED action does to one row, in a 14 pt gutter before its label.
5	     5	///
6	     6	/// A row's mark is derived from two lists of `"group.key"` paths: the keys
7	     7	/// its control WRITES — taken from the row's own `ops(read())` at build time,
8	     8	/// so a write that lands on the action's end patch and one that lands on the
9	     9	/// base props name the same key — and the keys it only FOLLOWS (Gain follows
10	    10	/// Volume). Both empty is `.none`, action or no action: a row that says
11	    11	/// nothing about what it writes (a readout, a Document-tab row) is never
12	    12	/// marked ⊘ by omission.
13	    13	enum RowMark: Equatable {
14	    14	    /// Nothing to say — the gutter stays blank.
15	    15	    case none
16	    16	    /// ◆ — the row writes a key the selected action's end patch holds.
17	    17	    case keyed
18	    18	    /// ◆ and "at end" — the same, for a discrete control, which switches at
19	    19	    /// the action's end rather than ramping.
20	    20	    case keyedAtEnd
21	    21	    /// ◇ — ANOTHER action keys it; the number is that action's time-order
22	    22	    /// number (`ActionBands.ordered`).
23	    23	    case other(Int)
24	    24	    /// ○ — the row follows a keyed value without writing it.
25	    25	    case follows
26	    26	    /// ⊘ — the row writes the clip whatever is selected (CI-3, motion, a
27	    27	    /// list's length): the selected action cannot animate it.
28	    28	    case notAnimatable
29	    29	}
